import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup, FormArray, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { JobDescriptionService } from '../../services/job-description.service';
import { JobDescription } from '../../models/job-description.model';

export interface JobOffer {
  id?: number;
  title: string;
  company: string;
  location: string;
  salary_min?: number;
  salary_max?: number;
  contract_type: string;
  work_mode: string;
  application_deadline: string;
  description: string;
  requirements: string[];
  benefits: string[];
  job_description_id: number;
  status: 'draft' | 'published' | 'closed';
  created_by: number;
  published_at?: string;
  views_count?: number;
  applications_count?: number;
}

@Component({
  selector: 'app-job-offer',
  standalone: true,
  imports: [CommonModule, FormsModule, ReactiveFormsModule],
  templateUrl: './job-offer.component.html',
  styleUrls: ['./job-offer.component.css']
})
export class JobOfferComponent implements OnInit {
  jobOfferForm: FormGroup;
  jobDescriptions: JobDescription[] = [];
  selectedJobDescription: JobDescription | null = null;
  loading = false;
  saving = false;
  errorMessage: string | null = null;
  successMessage: string | null = null;
  previewMode = false;

  contractTypes = [
    { value: 'CDI', label: 'CDI - Contrat à Durée Indéterminée' },
    { value: 'CDD', label: 'CDD - Contrat à Durée Déterminée' },
    { value: 'Stage', label: 'Stage' },
    { value: 'Freelance', label: 'Freelance/Consultant' },
    { value: 'Apprentissage', label: 'Contrat d\'Apprentissage' }
  ];

  workModes = [
    { value: 'Présentiel', label: 'Présentiel' },
    { value: 'Télétravail', label: 'Télétravail complet' },
    { value: 'Hybride', label: 'Hybride (Présentiel + Télétravail)' },
    { value: 'Flexible', label: 'Flexible selon les besoins' }
  ];

  constructor(
    private formBuilder: FormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private jobDescriptionService: JobDescriptionService
  ) {
    this.jobOfferForm = this.formBuilder.group({
      title: ['', [Validators.required, Validators.minLength(5)]],
      company: ['Abshore', Validators.required],
      location: ['', Validators.required],
      salary_min: [''],
      salary_max: [''],
      contract_type: ['CDI', Validators.required],
      work_mode: ['Hybride', Validators.required],
      application_deadline: ['', Validators.required],
      description: ['', [Validators.required, Validators.minLength(50)]],
      requirements: this.formBuilder.array([]),
      benefits: this.formBuilder.array([]),
      job_description_id: ['', Validators.required],
      status: ['draft']
    });
  }

  ngOnInit(): void {
    this.loadJobDescriptions();
    this.setDefaultDeadline();

    const jobDescriptionId = this.route.snapshot.queryParams['jobDescriptionId'];
    if (jobDescriptionId) {
      this.loadJobDescriptionAndPrefill(parseInt(jobDescriptionId));
    }
  }

  get requirementsArray(): FormArray {
    return this.jobOfferForm.get('requirements') as FormArray;
  }

  get benefitsArray(): FormArray {
    return this.jobOfferForm.get('benefits') as FormArray;
  }

  loadJobDescriptions(): void {
    this.jobDescriptionService.getJobDescriptions().subscribe({
      next: (res) => this.jobDescriptions = res,
      error: () => this.errorMessage = 'Erreur lors du chargement des fiches de poste.'
    });
  }

  loadJobDescriptionAndPrefill(jobDescriptionId: number): void {
    this.jobDescriptionService.getJobDescriptionById(jobDescriptionId).subscribe({
      next: (jd) => {
        this.selectedJobDescription = jd;
        this.prefillFormFromJobDescription(jd);
      },
      error: () => this.errorMessage = 'Erreur lors du chargement de la fiche de poste.'
    });
  }

  onJobDescriptionChange(): void {
    const id = this.jobOfferForm.get('job_description_id')?.value;
    if (id) this.loadJobDescriptionAndPrefill(parseInt(id));
  }

  prefillFormFromJobDescription(jd: JobDescription): void {
    const title = `${jd.emploi} - ${jd.filiere_activite}`;
    let description = `Nous recherchons un(e) ${jd.emploi} pour rejoindre notre équipe ${jd.filiere_activite}.\n\n`;

    if (jd.finalite) description += `**Finalité du poste :**\n${jd.finalite}\n\n`;
    if (jd.missions?.length) {
      description += `**Missions principales :**\n`;
      jd.missions.forEach(m => description += `• ${m.mission}\n`);
    }

    this.jobOfferForm.patchValue({
      title,
      description,
      job_description_id: jd.id
    });

    this.clearFormArray(this.requirementsArray);
    jd.requiredSkills?.forEach(skill => {
      const requirement = `${skill.skill?.name || 'Compétence inconnue'} - ${skill.skill_level?.level_name || 'Niveau requis'}`;
      this.addRequirement(requirement);
    });
    if (jd.niveau_exp) this.addRequirement(`Expérience : ${jd.niveau_exp}`);

    this.clearFormArray(this.benefitsArray);
    ['Télétravail partiel possible', 'Formation continue', 'Mutuelle', 'Tickets restaurant'].forEach(b => this.addBenefit(b));
  }

  setDefaultDeadline(): void {
    const deadline = new Date();
    deadline.setDate(deadline.getDate() + 30);
    this.jobOfferForm.patchValue({ application_deadline: deadline.toISOString().split('T')[0] });
  }

  addRequirement(text = ''): void { this.requirementsArray.push(this.formBuilder.control(text, Validators.required)); }
  removeRequirement(index: number): void { this.requirementsArray.removeAt(index); }
  addBenefit(text = ''): void { this.benefitsArray.push(this.formBuilder.control(text, Validators.required)); }
  removeBenefit(index: number): void { this.benefitsArray.removeAt(index); }
  clearFormArray(array: FormArray): void { while (array.length) array.removeAt(0); }

  togglePreview(): void { this.previewMode = !this.previewMode; }

  onSubmit(): void {
    if (this.jobOfferForm.valid) {
      this.saving = true;
      const jobOfferData: JobOffer = { ...this.jobOfferForm.value, requirements: this.requirementsArray.value, benefits: this.benefitsArray.value, created_by: 1 };
      console.log('Job Offer Data:', jobOfferData);

      setTimeout(() => {
        this.successMessage = 'Offre d\'emploi créée avec succès !';
        this.saving = false;
        setTimeout(() => this.router.navigate(['/job-offer/create']), 2000);
      }, 1000);
    } else {
      this.markFormGroupTouched();
      this.errorMessage = 'Veuillez remplir tous les champs obligatoires.';
    }
  }

  saveDraft(): void { this.jobOfferForm.patchValue({ status: 'draft' }); this.onSubmit(); }
  publishOffer(): void { this.jobOfferForm.patchValue({ status: 'published' }); this.onSubmit(); }

  private markFormGroupTouched(): void {
    Object.keys(this.jobOfferForm.controls).forEach(key => {
      const control = this.jobOfferForm.get(key);
      if (control instanceof FormArray) {
        control.controls.forEach(c => c.markAsTouched());
      } else {
        control?.markAsTouched();
      }
    });
  }

  getFieldError(fieldName: string): string | null {
    const field = this.jobOfferForm.get(fieldName);
    if (field?.errors && field.touched) {
      if (field.errors['required']) return 'Ce champ est requis';
      if (field.errors['minlength']) return `Minimum ${field.errors['minlength'].requiredLength} caractères`;
    }
    return null;
  }

  getSalaryRange(): { min: number; max: number } {
    if (!this.selectedJobDescription) return { min: 30000, max: 50000 };
    const baseRanges: { [key: string]: { min: number; max: number } } = {
      'Junior': { min: 28000, max: 38000 },
      'Confirmé': { min: 38000, max: 55000 },
      'Senior': { min: 55000, max: 75000 },
      'Expert': { min: 75000, max: 100000 }
    };
    const level = this.selectedJobDescription.niveau_exp || 'Confirmé';
    return baseRanges[level] || { min: 35000, max: 50000 };
  }

  applySuggestedSalary(): void {
    const range = this.getSalaryRange();
    this.jobOfferForm.patchValue({ salary_min: range.min, salary_max: range.max });
  }

  getLocationSuggestions(): string[] {
    return ['Tunis, Tunisie', 'Sfax, Tunisie', 'Bizerte, Tunisie', 'Sousse, Tunisie', 'Télétravail complet', 'Tunisie (Télétravail possible)'];
  }

  applyLocationSuggestion(location: string): void {
    this.jobOfferForm.patchValue({ location });
  }
}
